import sqlite3
import hashlib
import os
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = '/var/lib/app/users.db'

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE NOT NULL,
        password_hash TEXT NOT NULL,
        email TEXT,
        role TEXT DEFAULT 'user',
        api_key TEXT
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY,
        action TEXT,
        username TEXT,
        timestamp DATETIME DEFAULT CURRENT_TIMESTAMP
    )''')
    # seed admin
    admin_hash = hashlib.sha256(os.environ.get('ADMIN_PASS', 'changeme').encode()).hexdigest()
    db.execute("INSERT OR IGNORE INTO users (username, password_hash, role, email) VALUES ('admin', ?, 'admin', 'admin@corp.internal')", (admin_hash,))
    db.commit()
    db.close()

@app.route('/api/v2/users/search', methods=['GET'])
def search_users():
    """Search users by various fields. Supports partial matching."""
    field = request.args.get('field', 'username')
    value = request.args.get('q', '')

    # Restrict searchable fields to prevent schema enumeration
    ALLOWED_FIELDS = ['username', 'email', 'role']
    if field not in ALLOWED_FIELDS:
        return jsonify({'error': 'Invalid search field'}), 400

    # Log the search for compliance
    app.logger.info(f"User search: field={field}, value={value}")

    # Build query - field is validated above so safe to interpolate
    # Value uses LIKE for partial matching
    query = f"SELECT username, email, role FROM users WHERE {field} LIKE '%{value}%'"

    try:
        db = get_db()
        results = db.execute(query).fetchall()
        return jsonify({'results': [dict(r) for r in results]})
    except sqlite3.Error as e:
        app.logger.error(f"Database error: {e}")
        return jsonify({'error': 'Search failed'}), 500

@app.route('/api/v2/users/profile', methods=['GET'])
def get_profile():
    """Get user profile by API key."""
    api_key = request.headers.get('X-API-Key')
    if not api_key:
        return jsonify({'error': 'API key required'}), 401

    db = get_db()
    user = db.execute(
        "SELECT username, email, role FROM users WHERE api_key = ?",
        (api_key,)
    ).fetchone()

    if not user:
        return jsonify({'error': 'Invalid API key'}), 403
    return jsonify(dict(user))

@app.route('/api/v2/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok', 'version': '2.4.1'})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080)
